import type { ReactNode } from "react";
import { Header } from "@/components/headers/header";
import MainLayout from "@/components/layouts/main-layout";

export default function ChangelogLayout({ children }: { children: ReactNode }) {
  return (
    <MainLayout header={<Header variant="minimal" />} footer={null}>
      <div className="mx-auto max-w-4xl px-4 py-12 sm:px-6 lg:px-8">{children}</div>
    </MainLayout>
  );
}

import type { Metadata } from "next";
import { Suspense } from "react";
import { BlogPostListSkeleton } from "@/components/modules/blog/skeleton";
import { constructMetadata } from "@/config/metadata";
import { siteConfig } from "@/config/site-config";
import { ChangelogEntries } from "./_components/changelog-entries";

export const dynamic = "force-dynamic";
export const revalidate = 0;

export const metadata: Metadata = constructMetadata({
  title: `Changelog | ${siteConfig.title}`,
  description: `See what's new in ${siteConfig.title}. Latest updates, features, and fixes.`,
});

export default function ChangelogPage() {
  return (
    <div className="mx-auto w-full max-w-3xl">
      <header className="mb-12">
        <h1 className="text-4xl font-bold tracking-tight">Changelog</h1>
        <p className="mt-2 text-lg text-muted-foreground">New updates, features, and fixes.</p>
      </header>

      {/* In-page Suspense keeps the skeleton without a segment loading.tsx,
			    which would also wrap [...slug] and break its 404 status. */}
      <Suspense fallback={<BlogPostListSkeleton count={5} />}>
        <ChangelogEntries />
      </Suspense>
    </div>
  );
}

import { ArrowLeft } from "lucide-react";
import type { Metadata } from "next";
import { headers } from "next/headers";
import Link from "next/link";
import { notFound } from "next/navigation";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import { Badge } from "@/components/ui/badge";
import { buttonVariants } from "@/components/ui/button";
import { constructMetadata } from "@/config/metadata";
import { siteConfig } from "@/config/site-config";
import { getChangelogEntries, getChangelogEntry } from "@/lib/changelog";
import { describeEntrySize } from "@/lib/changelog-types";
import { cn } from "@/lib/utils";
import { formatDate, formatDateTimeAttribute } from "@/lib/utils/format-date";

export const dynamic = "force-dynamic";
export const revalidate = 0;

interface Props {
  params: Promise<{ slug: string[] }>;
}

export async function generateStaticParams() {
  const entries = await getChangelogEntries();
  return entries.map((entry) => ({
    slug: entry.slug.includes("/") ? entry.slug.split("/") : [entry.slug],
  }));
}

export async function generateMetadata({ params }: Props): Promise<Metadata> {
  const resolvedParams = await params;
  const slug = resolvedParams.slug.join("/");
  const entry = await getChangelogEntry(slug);

  if (!entry) {
    return constructMetadata({
      title: `Changelog | ${siteConfig.title}`,
    });
  }

  return constructMetadata({
    title: `${entry.title} | ${siteConfig.title} Changelog`,
    description: entry.description,
  });
}

export default async function ChangelogEntryPage({ params }: Props) {
  await headers();
  const resolvedParams = await params;
  const slug = resolvedParams.slug.join("/");
  const entry = await getChangelogEntry(slug);

  if (!entry) {
    notFound();
  }

  const dateTimeAttr = formatDateTimeAttribute(entry.publishedAt);
  const displayDate = formatDate(entry.publishedAt);
  const entrySize = describeEntrySize(entry);

  return (
    <div className="mx-auto w-full max-w-3xl">
      <Link
        href="/changelog"
        className={cn(
          buttonVariants({ variant: "ghost", size: "sm" }),
          "mb-8 h-auto p-0 text-muted-foreground hover:text-foreground"
        )}
      >
        <ArrowLeft className="mr-2 h-4 w-4" />
        Back to Changelog
      </Link>

      <article>
        <header className="mb-8 border-b pb-6">
          <div className="mb-2 flex items-center gap-3">
            {entry.badge && (
              <Badge variant="secondary" className="font-mono">
                {entry.badge}
              </Badge>
            )}
            {displayDate && (
              <time dateTime={dateTimeAttr} className="text-sm text-muted-foreground">
                {displayDate}
              </time>
            )}
            {entrySize && <span className="text-xs text-muted-foreground">{entrySize}</span>}
          </div>
          <h1 className="text-3xl font-bold tracking-tight">{entry.title}</h1>
          {entry.description && (
            <p className="mt-2 text-lg text-muted-foreground">{entry.description}</p>
          )}
        </header>

        <div className="prose max-w-none prose-neutral dark:prose-invert">
          <ReactMarkdown remarkPlugins={[remarkGfm]}>{entry.content}</ReactMarkdown>
        </div>
      </article>
    </div>
  );
}

import { BlogPostSkeleton } from "@/components/modules/blog/skeleton";

export default function Loading() {
  return <BlogPostSkeleton />;
}

import fs from "node:fs/promises";
import path from "node:path";
import { parseChangelogMarkdown } from "@/lib/changelog-markdown";
import type { ChangelogEntry } from "@/lib/changelog-types";
import { changelogManifest } from "@/lib/generated/changelog-manifest";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
export type { ChangelogEntry } from "@/lib/changelog-types";

interface GitHubCommit {
  sha: string;
  commit: {
    message: string;
    author: { date: string; name: string };
  };
}

interface GitHubTag {
  name: string;
  commit: { sha: string };
}

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------
const REPO_OWNER = process.env.GITHUB_REPO_OWNER ?? "lacymorrow";
const REPO_NAME = process.env.GITHUB_REPO_NAME ?? "shipkit";
const GITHUB_API = `https://api.github.com/repos/${REPO_OWNER}/${REPO_NAME}`;
const COMMITS_PER_PAGE = 100;
const MAX_PAGES = 5; // 500 commits max

/**
 * Path to the repo's Keep a Changelog file, looked for on disk first and then in the
 * configured GitHub repo. Set CHANGELOG_PATH to "" to skip this source entirely.
 */
const CHANGELOG_PATH = process.env.CHANGELOG_PATH ?? "CHANGELOG.md";

// ---------------------------------------------------------------------------
// GitHub fetcher (works unauthenticated for public repos, uses token if set)
// ---------------------------------------------------------------------------
async function ghFetch<T>(endpoint: string): Promise<T> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
  };
  const token = process.env.GITHUB_TOKEN ?? process.env.GITHUB_ACCESS_TOKEN;
  if (token) {
    headers.Authorization = `Bearer ${token}`;
  }

  const res = await fetch(`${GITHUB_API}${endpoint}`, { headers });
  if (!res.ok) {
    const errorBody = await res.text().catch(() => "");
    throw new Error(`GitHub API ${res.status}: ${endpoint} - ${errorBody}`);
  }
  return res.json() as Promise<T>;
}

// ---------------------------------------------------------------------------
// Fetch all commits (paginated)
// ---------------------------------------------------------------------------
async function fetchCommits(): Promise<GitHubCommit[]> {
  const all: GitHubCommit[] = [];
  for (let page = 1; page <= MAX_PAGES; page++) {
    const batch = await ghFetch<GitHubCommit[]>(
      `/commits?per_page=${COMMITS_PER_PAGE}&page=${page}`
    );
    all.push(...batch);
    if (batch.length < COMMITS_PER_PAGE) break;
  }
  return all;
}

// ---------------------------------------------------------------------------
// Fetch tags and build sha->tag map
// ---------------------------------------------------------------------------
async function fetchTagMap(): Promise<Map<string, string>> {
  const tags = await ghFetch<GitHubTag[]>("/tags?per_page=100");
  const map = new Map<string, string>();
  for (const tag of tags) {
    map.set(tag.commit.sha, tag.name);
  }
  return map;
}

// ---------------------------------------------------------------------------
// Commit message parsing
// ---------------------------------------------------------------------------
const NOISE = [
  /^auto commit$/i,
  /^merge /i,
  /^Merge pull request/,
  /^Merge branch/,
  /^initial commit$/i,
  /^wip$/i,
  /^\.$/,
];

function isNoise(msg: string): boolean {
  return NOISE.some((re) => re.test(msg));
}

interface ParsedCommit {
  type: string;
  scope: string | null;
  subject: string;
  breaking: boolean;
}

function parseConventional(message: string): ParsedCommit | null {
  const match = /^(\w+)(?:\(([^)]+)\))?(!?):\s*(.+)/.exec(message);
  if (!match) return null;
  // Regex above guarantees groups 1 and 4 exist on a successful match.
  const type = match[1];
  const subject = match[4];
  if (!type || !subject) return null;
  return {
    type: type.toLowerCase(),
    scope: match[2] ?? null,
    subject,
    breaking: match[3] === "!",
  };
}

const TYPE_LABELS: Record<string, string> = {
  feat: "New Features",
  fix: "Bug Fixes",
  perf: "Performance",
  refactor: "Improvements",
  docs: "Documentation",
  style: "Styling",
  chore: "Maintenance",
  ci: "CI/CD",
  test: "Testing",
  build: "Build",
};

// ---------------------------------------------------------------------------
// Grouping: by tag or by week
// ---------------------------------------------------------------------------

interface CommitGroup {
  label: string;
  slug: string;
  date: string; // ISO date of the most recent commit
  commits: GitHubCommit[];
  isRelease: boolean;
}

function groupCommits(commits: GitHubCommit[], tagMap: Map<string, string>): CommitGroup[] {
  const groups: CommitGroup[] = [];
  let currentGroup: GitHubCommit[] = [];
  let currentTag: string | null = null;

  // Walk commits newest-first, split on tags
  for (const commit of commits) {
    const tag = tagMap.get(commit.sha);
    if (tag && currentGroup.length > 0) {
      // Close previous group as "Recent Updates"
      const newestDate = currentGroup[0]?.commit.author.date ?? new Date().toISOString();
      const groupLabel = currentTag ?? "Recent Updates";
      const groupSlug = currentTag
        ? currentTag.replace(/[^a-zA-Z0-9.-]/g, "-").toLowerCase()
        : `updates-${newestDate.slice(0, 10)}`;

      groups.push({
        label: groupLabel,
        slug: groupSlug,
        date: newestDate,
        commits: currentGroup,
        isRelease: !!currentTag,
      });
      currentGroup = [];
    }
    if (tag) currentTag = tag;
    currentGroup.push(commit);
  }

  // Final group
  if (currentGroup.length > 0) {
    const newestDate = currentGroup[0]?.commit.author.date ?? new Date().toISOString();
    const groupLabel = currentTag ?? "Recent Updates";
    const groupSlug = currentTag
      ? currentTag.replace(/[^a-zA-Z0-9.-]/g, "-").toLowerCase()
      : `updates-${newestDate.slice(0, 10)}`;

    groups.push({
      label: groupLabel,
      slug: groupSlug,
      date: newestDate,
      commits: currentGroup,
      isRelease: !!currentTag,
    });
  }

  // If no tags at all, keep everything as one "Recent Updates" group
  if (tagMap.size === 0 && commits.length > 0) {
    const newestDate = commits[0]?.commit.author.date ?? new Date().toISOString();
    return [
      {
        label: "Recent Updates",
        slug: `updates-${newestDate.slice(0, 10)}`,
        date: newestDate,
        commits,
        isRelease: false,
      },
    ];
  }

  return groups;
}

// ---------------------------------------------------------------------------
// Render a group into a changelog entry
// ---------------------------------------------------------------------------
function renderEntry(group: CommitGroup): ChangelogEntry {
  const meaningful = group.commits.filter((c) => !isNoise(c.commit.message.split("\n")[0]!));

  // Bucket by conventional commit type
  const buckets = new Map<string, string[]>();
  const uncategorized: string[] = [];

  for (const c of meaningful) {
    const firstLine = c.commit.message.split("\n")[0]!;
    const parsed = parseConventional(firstLine);
    if (parsed) {
      const label = TYPE_LABELS[parsed.type] ?? "Other";
      if (!buckets.has(label)) buckets.set(label, []);
      buckets.get(label)?.push(parsed.subject);
    } else {
      uncategorized.push(firstLine);
    }
  }

  // Build markdown
  const sections: string[] = [];
  const sectionOrder = Object.values(TYPE_LABELS);
  for (const label of sectionOrder) {
    const items = buckets.get(label);
    if (!items?.length) continue;
    sections.push(`## ${label}\n\n${items.map((s) => `- ${s}`).join("\n")}`);
  }
  if (uncategorized.length) {
    sections.push(`## Changes\n\n${uncategorized.map((s) => `- ${s}`).join("\n")}`);
  }

  const content = sections.join("\n\n") || "Maintenance and internal improvements.";

  // Count features and fixes for description
  const featureCount = buckets.get("New Features")?.length ?? 0;
  const fixCount = buckets.get("Bug Fixes")?.length ?? 0;
  const parts: string[] = [];
  if (featureCount) parts.push(`${featureCount} new feature${featureCount > 1 ? "s" : ""}`);
  if (fixCount) parts.push(`${fixCount} bug fix${fixCount > 1 ? "es" : ""}`);
  if (!parts.length) parts.push(`${meaningful.length} update${meaningful.length !== 1 ? "s" : ""}`);
  const description = parts.join(", ");

  // Badge
  const badge = group.isRelease ? group.label : undefined;

  // Categories from commit types
  const categories = Array.from(buckets.keys());

  return {
    title: group.isRelease ? `Release ${group.label}` : group.label,
    slug: group.slug,
    content,
    description,
    publishedAt: group.date.slice(0, 10),
    badge,
    categories,
    commitCount: group.commits.length,
  };
}

// ---------------------------------------------------------------------------
// Markdown file-based changelog (src/content/changelog/*.md)
// Uses the build-time manifest (generated by scripts/prebuild-content.mjs)
// with a runtime fs.readdir fallback for local development.
// ---------------------------------------------------------------------------
const CHANGELOG_DIR = path.join(process.cwd(), "src/content/changelog");

function manifestToEntries(manifest: typeof changelogManifest): ChangelogEntry[] {
  return manifest.map((entry) => {
    const slug = (entry.frontmatter.slug as string) ?? entry.filename.replace(/\.mdx?$/, "");
    return {
      title: (entry.frontmatter.title as string) ?? slug,
      slug,
      content: entry.content,
      description: (entry.frontmatter.description as string) ?? "",
      publishedAt: (entry.frontmatter.publishedAt as string) ?? "",
      badge: entry.frontmatter.badge as string | undefined,
      categories: (entry.frontmatter.categories as string[]) ?? [],
      commitCount: (entry.frontmatter.commitCount as number) ?? 0,
    } satisfies ChangelogEntry;
  });
}

async function getMarkdownEntries(): Promise<ChangelogEntry[]> {
  if (changelogManifest.length > 0) {
    const entries = manifestToEntries(changelogManifest);
    return entries.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
  }

  let filenames: string[];
  try {
    filenames = await fs.readdir(CHANGELOG_DIR);
  } catch {
    return [];
  }

  const mdFiles = filenames.filter((f) => f.endsWith(".md") || f.endsWith(".mdx"));
  if (mdFiles.length === 0) return [];

  const { default: matter } = await import("gray-matter");
  const entries = await Promise.all(
    mdFiles.map(async (filename) => {
      const filePath = path.join(CHANGELOG_DIR, filename);
      const fileContent = await fs.readFile(filePath, "utf-8");
      const { data, content } = matter(fileContent);

      const slug = data.slug ?? filename.replace(/\.mdx?$/, "");

      return {
        title: data.title ?? slug,
        slug,
        content: content.trim(),
        description: data.description ?? "",
        publishedAt: data.publishedAt ?? "",
        badge: data.badge,
        categories: data.categories ?? [],
        commitCount: data.commitCount ?? 0,
      } satisfies ChangelogEntry;
    })
  );

  return entries.sort((a, b) => b.publishedAt.localeCompare(a.publishedAt));
}

// ---------------------------------------------------------------------------
// Repo CHANGELOG.md (Keep a Changelog format)
//
// Read from disk when the site ships its own changelog, otherwise fetched from the
// configured GitHub repo. This is what lets a downstream ShipKit site publish the
// changelog of whatever repo it is the website for.
// ---------------------------------------------------------------------------
interface GitHubContentFile {
  content?: string;
  encoding?: string;
}

async function readLocalChangelogFile(): Promise<string | null> {
  try {
    return await fs.readFile(path.join(process.cwd(), CHANGELOG_PATH), "utf-8");
  } catch {
    return null;
  }
}

async function fetchRemoteChangelogFile(): Promise<string | null> {
  try {
    const file = await ghFetch<GitHubContentFile>(`/contents/${encodeURI(CHANGELOG_PATH)}`);
    if (!file.content || file.encoding !== "base64") return null;
    return Buffer.from(file.content, "base64").toString("utf-8");
  } catch {
    // A repo without a CHANGELOG.md is the normal case, not an error worth surfacing.
    return null;
  }
}

async function getRepoChangelogEntries(): Promise<ChangelogEntry[]> {
  if (!CHANGELOG_PATH) return [];

  const source = (await readLocalChangelogFile()) ?? (await fetchRemoteChangelogFile());
  if (!source) return [];

  return parseChangelogMarkdown(source);
}

// ---------------------------------------------------------------------------
// GitHub API-based changelog (fallback when no .md files exist)
// ---------------------------------------------------------------------------
async function getGitHubEntries(): Promise<ChangelogEntry[]> {
  const [commits, tagMap] = await Promise.all([fetchCommits(), fetchTagMap()]);
  const groups = groupCommits(commits, tagMap);
  const entries = groups.map(renderEntry);
  return entries.filter((e) => e.commitCount > 0);
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------
/**
 * Loads changelog entries from the first source that has something to say:
 *
 * 1. Curated per-entry markdown in `src/content/changelog/`, for sites that write
 *    their own release posts.
 * 2. The repo's `CHANGELOG.md`, on disk or from GitHub. One canonical changelog,
 *    written once, rendered here.
 * 3. Generated from the repo's commits and tags, so a site with neither still
 *    gets a changelog out of the box.
 */
export async function getChangelogEntries(): Promise<ChangelogEntry[]> {
  try {
    const mdEntries = await getMarkdownEntries();
    if (mdEntries.length > 0) return mdEntries;

    const repoEntries = await getRepoChangelogEntries();
    if (repoEntries.length > 0) return repoEntries;

    return await getGitHubEntries();
  } catch (err) {
    console.error("[changelog] Failed to load changelog:", err);
    return [];
  }
}

export async function getChangelogEntry(slug: string): Promise<ChangelogEntry | null> {
  const entries = await getChangelogEntries();
  return entries.find((e) => e.slug === slug) ?? null;
}

/**
 * @fileoverview Parses a Keep a Changelog formatted CHANGELOG.md into changelog entries.
 * @module lib/changelog-markdown
 *
 * This is the source that lets any ShipKit site publish a web changelog straight from
 * the CHANGELOG.md that already lives in its repo, with no per-entry markdown to maintain.
 *
 * Format reference: https://keepachangelog.com/en/1.1.0/
 *
 * Pure string in, entries out. No filesystem or network access, so it stays testable.
 */

import type { ChangelogEntry } from "@/lib/changelog-types";

/**
 * Matches a release heading and pulls out the version, the release date, and a YANKED marker.
 *
 * Handles the shapes that appear in the wild:
 *   ## [1.2.3] - 2026-09-22
 *   ## [Unreleased]
 *   ## 1.2.3 - 2026-09-22
 *   ## [0.0.5] - 2014-12-13 [YANKED]
 *   ## [0.4.1.2] - 2025-06-29      (not every project is strict semver)
 *
 * The separator class accepts a hyphen, an en dash or an em dash, because hand-edited
 * files use all three. Those two characters appear here only as regex input to match,
 * never as prose.
 */
const RELEASE_HEADING =
  /^##\s+(?:\[([^\]]+)\]|([^\s[]+))\s*(?:[-–—]\s*(\d{4}-\d{2}-\d{2}))?\s*(\[YANKED\])?\s*$/i;

/** Matches a `### Added` style category heading. */
const CATEGORY_HEADING = /^###\s+(.+?)\s*$/;

/** Matches a link reference definition, e.g. `[1.2.3]: https://github.com/...`. */
const LINK_DEFINITION = /^\[[^\]]+\]:\s*\S+/;

/** Matches a top level bullet. Nested bullets are body text, not separate changes. */
const TOP_LEVEL_BULLET = /^[-*+]\s+\S/;

/**
 * How Keep a Changelog categories read in a one line summary.
 * Anything unrecognised falls back to a generic change count.
 */
const CATEGORY_SUMMARY: Record<string, { singular: string; plural: string }> = {
  added: { singular: "new feature", plural: "new features" },
  changed: { singular: "change", plural: "changes" },
  deprecated: { singular: "deprecation", plural: "deprecations" },
  removed: { singular: "removal", plural: "removals" },
  fixed: { singular: "bug fix", plural: "bug fixes" },
  security: { singular: "security fix", plural: "security fixes" },
};

/** Order used when building the description, so summaries read consistently. */
const SUMMARY_ORDER = ["added", "changed", "fixed", "removed", "deprecated", "security"];

interface RawSection {
  label: string;
  date: string;
  yanked: boolean;
  lines: string[];
}

/**
 * Splits the file into release sections, dropping the preamble and any trailing
 * link reference definitions.
 */
function splitSections(markdown: string): RawSection[] {
  const sections: RawSection[] = [];
  let current: RawSection | null = null;

  for (const line of markdown.split(/\r?\n/)) {
    const heading = RELEASE_HEADING.exec(line);

    if (heading) {
      if (current) sections.push(current);
      current = {
        label: (heading[1] ?? heading[2] ?? "").trim(),
        date: heading[3] ?? "",
        yanked: Boolean(heading[4]),
        lines: [],
      };
      continue;
    }

    // Everything before the first release heading is the file's preamble.
    if (!current) continue;

    // Link definitions live at the foot of the file and would otherwise be
    // swallowed into the oldest release's body.
    if (LINK_DEFINITION.test(line)) continue;

    current.lines.push(line);
  }

  if (current) sections.push(current);
  return sections.filter((section) => section.label.length > 0);
}

/** Counts top level bullets under each `###` category heading. */
function countByCategory(lines: string[]): Map<string, number> {
  const counts = new Map<string, number>();
  let category: string | null = null;

  for (const line of lines) {
    const heading = CATEGORY_HEADING.exec(line);
    if (heading?.[1]) {
      category = heading[1];
      if (!counts.has(category)) counts.set(category, 0);
      continue;
    }
    if (category && TOP_LEVEL_BULLET.test(line)) {
      counts.set(category, (counts.get(category) ?? 0) + 1);
    }
  }

  return counts;
}

/**
 * Builds the one line summary shown on the changelog index,
 * e.g. "3 new features, 2 bug fixes".
 */
function buildDescription(counts: Map<string, number>, totalChanges: number): string {
  const parts: string[] = [];

  for (const key of SUMMARY_ORDER) {
    const entry = [...counts.entries()].find(([label]) => label.toLowerCase() === key);
    const count = entry?.[1] ?? 0;
    if (count === 0) continue;
    const words = CATEGORY_SUMMARY[key];
    if (!words) continue;
    parts.push(`${count} ${count === 1 ? words.singular : words.plural}`);
  }

  if (parts.length > 0) return parts.join(", ");
  if (totalChanges > 0) return `${totalChanges} change${totalChanges === 1 ? "" : "s"}`;
  return "Maintenance and internal improvements.";
}

/** Turns a version label into a URL safe slug, matching the GitHub source's scheme. */
function toSlug(label: string): string {
  return (
    label
      .replace(/[^a-zA-Z0-9.-]/g, "-")
      .replace(/-+/g, "-")
      .replace(/^-|-$/g, "")
      .toLowerCase() || "release"
  );
}

/**
 * Parses a Keep a Changelog file into entries, newest first.
 *
 * Entry order follows the file rather than the parsed dates. Keep a Changelog already
 * requires newest first, and trusting the file keeps an undated `Unreleased` section at
 * the top where it belongs instead of sorting it to the bottom.
 */
export function parseChangelogMarkdown(markdown: string): ChangelogEntry[] {
  if (!markdown.trim()) return [];

  return splitSections(markdown).map((section) => {
    const counts = countByCategory(section.lines);
    const totalChanges = [...counts.values()].reduce((sum, n) => sum + n, 0);
    const isUnreleased = section.label.toLowerCase() === "unreleased";

    const content = section.lines.join("\n").trim();
    const categories = [...counts.keys()];

    const description = section.yanked
      ? `Withdrawn release. ${buildDescription(counts, totalChanges)}`
      : buildDescription(counts, totalChanges);

    return {
      // "Release 1.2.3" mirrors the GitHub commit source so both look the same on the page.
      title: isUnreleased ? "Unreleased" : `Release ${section.label}`,
      slug: toSlug(section.label),
      content,
      description,
      publishedAt: section.date,
      badge: section.yanked ? `${section.label} (yanked)` : section.label,
      categories,
      // A CHANGELOG file says nothing about commits. Report the number of documented
      // changes instead, and let the UI label it accordingly.
      commitCount: 0,
      changeCount: totalChanges,
    } satisfies ChangelogEntry;
  });
}

/**
 * @fileoverview Shared changelog types.
 * @module lib/changelog-types
 *
 * Kept in its own module so the markdown parser and the loader can share the shape
 * without importing each other.
 */

export interface ChangelogEntry {
  title: string;
  slug: string;
  content: string;
  description: string;
  publishedAt: string;
  badge?: string;
  categories: string[];
  /** Commits behind this entry. Zero when the source is a written changelog rather than git. */
  commitCount: number;
  /** Documented changes behind this entry. Set when the source is a written changelog. */
  changeCount?: number;
}

/**
 * Describes how much is behind an entry, in the unit the source actually knows about.
 * Entries generated from git count commits; entries read from a CHANGELOG.md count
 * documented changes. Returns an empty string when there is nothing honest to show.
 */
export function describeEntrySize(entry: ChangelogEntry): string {
  const count = entry.commitCount > 0 ? entry.commitCount : (entry.changeCount ?? 0);
  if (count <= 0) return "";

  const noun = entry.commitCount > 0 ? "commit" : "change";
  return `${count} ${noun}${count === 1 ? "" : "s"}`;
}
